import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("A vendor name already used in my tenant is refused in another letter case", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const existingName = uniqueName("Acme Freight");
  await factory.vendor({ as: "member", name: existingName });
  const sameNameDifferentCase = existingName.toLowerCase();

  // Act
  const response = await member.post("/api/vendors", {
    data: { name: sameNameDifferentCase, category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");
});
